module profit_maximizer(\n    input clk, rst_n, start,\n    input [2:0] num_candidates,\n    input [3:0] candidate_level0, candidate_level1, candidate_level2, candidate_level3,\n    input [3:0] candidate_level4, candidate_level5, candidate_level6, candidate_level7,\n    input signed [15:0] candidate_cost0, candidate_cost1, candidate_cost2, candidate_cost3,\n    input signed [15:0] candidate_cost4, candidate_cost5, candidate_cost6, candidate_cost7,\n    input signed [15:0] profit0, profit1, profit2, profit3, profit4, profit5, profit6, profit7,\n    input signed [15:0] profit8, profit9, profit10, profit11, profit12, profit13, profit14, profit15,\n    output reg signed [31:0] max_profit,\n    output reg done\n);\n\n    // State encoding\n    localparam [3:0] IDLE           = 4'd0;\n    localparam [3:0] INIT           = 4'd1;\n    localparam [3:0] PROCESS_CANDIDATE = 4'd2;\n    localparam [3:0] UPDATE_STATE   = 4'd3;\n    localparam [3:0] PROPAGATE      = 4'd4;\n    localparam [3:0] NEXT_COUNT     = 4'd5;\n    localparam [3:0] NEXT_CANDIDATE = 4'd6;\n    localparam [3:0] FINAL_SCAN     = 4'd7;\n    localparam [3:0] DONE_STATE     = 4'd8;\n\n    // Loop indices\n    integer i,j;\n    \n    // Constants\n    localparam MAX_LEVEL = 4'd15;\n    localparam MAX_COUNT = 4'd8;\n    \n    // DP table: [level][count]\n    reg signed [31:0] dp [0:15][0:8];\n    \n    // State registers\n    reg [3:0] state, next_state;\n    reg [3:0] level_counter, count_counter;\n    reg [3:0] candidate_index;\n    reg [7:0] cycle_count;  // Prevent infinite loops\n    localparam MAX_CYCLES = 8'd200;\n    \n    // Temporary registers\n    reg [3:0] current_level;\n    reg [3:0] current_count;\n    reg signed [31:0] current_value;\n    reg signed [31:0] next_value;\n    reg signed [31:0] max_temp;\n    \n    // Input mapping arrays\n    wire [3:0] level_val [0:7];\n    wire signed [15:0] cost_val [0:7];\n    wire signed [31:0] profit_val [0:15];\n    \n    assign level_val[0] = candidate_level0;\n    assign level_val[1] = candidate_level1;\n    assign level_val[2] = candidate_level2;\n    assign level_val[3] = candidate_level3;\n    assign level_val[4] = candidate_level4;\n    assign level_val[5] = candidate_level5;\n    assign level_val[6] = candidate_level6;\n    assign level_val[7] = candidate_level7;\n    \n    assign cost_val[0] = candidate_cost0;\n    assign cost_val[1] = candidate_cost1;\n    assign cost_val[2] = candidate_cost2;\n    assign cost_val[3] = candidate_cost3;\n    assign cost_val[4] = candidate_cost4;\n    assign cost_val[5] = candidate_cost5;\n    assign cost_val[6] = candidate_cost6;\n    assign cost_val[7] = candidate_cost7;\n    \n    assign profit_val[0] = $signed(profit0);\n    assign profit_val[1] = $signed(profit1);\n    assign profit_val[2] = $signed(profit2);\n    assign profit_val[3] = $signed(profit3);\n    assign profit_val[4] = $signed(profit4);\n    assign profit_val[5] = $signed(profit5);\n    assign profit_val[6] = $signed(profit6);\n    assign profit_val[7] = $signed(profit7);\n    assign profit_val[8] = $signed(profit8);\n    assign profit_val[9] = $signed(profit9);\n    assign profit_val[10] = $signed(profit10);\n    assign profit_val[11] = $signed(profit11);\n    assign profit_val[12] = $signed(profit12);\n    assign profit_val[13] = $signed(profit13);\n    assign profit_val[14] = $signed(profit14);\n    assign profit_val[15] = $signed(profit15);\n    \n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            max_profit <= 32'd0;\n            max_temp <= -32'sd1000000000;\n            level_counter <= 4'd0;\n            count_counter <= 4'd0;\n            candidate_index <= 4'd0;\n            cycle_count <= 8'd0;\n            current_level <= 4'd0;\n            current_count <= 4'd0;\n            current_value <= 32'd0;\n            next_value <= 32'd0;\n            \n            // Initialize DP array\n            for (i = 0; i <= MAX_LEVEL; i = i + 1) begin\n                for (j = 0; j <= MAX_COUNT; j = j + 1) begin\n                    dp[i][j] <= -32'sd1000000000;\n                end\n            end\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        state <= INIT;\n                        level_counter <= 4'd0;\n                        count_counter <= 4'd0;\n                        max_temp <= -32'sd1000000000;\n                        \n                        // Initialize dp[level][0] = 0\n                        for (i = 0; i <= MAX_LEVEL; i = i + 1) begin\n                            dp[i][0] <= 32'd0;\n                        end\n                    end\n                end\n                \n                INIT: begin\n                    // Finish initialization\n                    candidate_index <= num_candidates - 3'd1;\n                    state <= PROCESS_CANDIDATE;\n                end\n                \n                PROCESS_CANDIDATE: begin\n                    if (cycle_count > MAX_CYCLES) begin\n                        state <= FINAL_SCAN;\n                        level_counter <= 4'd0;\n                        max_temp <= -32'sd1000000000;\n                    end else if (candidate_index[3]) begin // candidate_index < 0\n                        state <= FINAL_SCAN;\n                        level_counter <= 4'd0;\n                        count_counter <= 4'd0;\n                        max_temp <= -32'sd1000000000;\n                    end else begin\n                        current_level <= level_val[candidate_index];\n                        count_counter <= MAX_COUNT;\n                        state <= UPDATE_STATE;\n                    end\n                end\n                \n                UPDATE_STATE: begin\n                    if (count_counter[3]) begin // count < 0\n                        state <= NEXT_CANDIDATE;\n                        candidate_index <= candidate_index - 4'd1;\n                    end else if (dp[current_level][count_counter] > -32'sd999999999) begin\n                        next_value <= dp[current_level][count_counter] +\n                                     cost_val[candidate_index] +\n                                     profit_val[current_level];\n                        current_count <= count_counter + 4'd1;\n                        state <= NEXT_COUNT;\n                    end else begin\n                        count_counter <= count_counter - 4'd1;\n                    end\n                end\n                \n                NEXT_COUNT: begin\n                    if (current_count <= MAX_COUNT) begin\n                        if (next_value > dp[current_level][current_count]) begin\n                            dp[current_level][current_count] <= next_value;\n                            current_value <= next_value;\n                            state <= PROPAGATE;\n                        end else begin\n                            count_counter <= count_counter - 4'd1;\n                            state <= UPDATE_STATE;\n                        end\n                    end else begin\n                        count_counter <= count_counter - 4'd1;\n                        state <= UPDATE_STATE;\n                    end\n                end\n                \n                PROPAGATE: begin\n                    if (current_level < MAX_LEVEL && current_count >= 4'd2) begin\n                        current_count <= current_count >> 1;\n                        current_level <= current_level + 4'd1;\n                        next_value <= current_value + (current_count >> 1)*profit_val[current_level + 1];\n                        state <= NEXT_COUNT;\n                    end else begin\n                        count_counter <= count_counter - 4'd1;\n                        state <= UPDATE_STATE;\n                    end\n                end\n                \n                FINAL_SCAN: begin\n                    if (level_counter > MAX_LEVEL) begin\n                        max_profit <= max_temp;\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end else if (count_counter <= 4'd1) begin\n                        if (dp[level_counter][count_counter] > max_temp) begin\n                            max_temp <= dp[level_counter][count_counter];\n                        end\n                        count_counter <= count_counter + 4'd1;\n                    end else begin\n                        level_counter <= level_counter + 4'd1;\n                        count_counter <= 4'd0;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule